'use strict';

function plain(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function sameKeys(value, keys) {
  const a = Object.keys(value).sort();
  const b = keys.slice().sort();
  return a.length === b.length && a.every((key, i) => key === b[i]);
}

function createChatState() {
  return { draft: '', messages: [] };
}

function applyChatAction(state, action) {
  if (!plain(state) || !sameKeys(state, ['draft', 'messages']) || typeof state.draft !== 'string' || !Array.isArray(state.messages)) {
    throw new TypeError('invalid state');
  }
  for (const message of state.messages) {
    if (!plain(message) || !sameKeys(message, ['id', 'sender', 'text']) ||
        typeof message.id !== 'string' || message.id.length === 0 ||
        typeof message.sender !== 'string' || message.sender.length === 0 || typeof message.text !== 'string') {
      throw new TypeError('invalid message');
    }
  }
  if (!plain(action) || typeof action.type !== 'string') throw new TypeError('invalid action');
  const copied = state.messages.map((message) => ({ ...message }));

  if (action.type === 'EDIT') {
    if (!sameKeys(action, ['type', 'text']) || typeof action.text !== 'string') throw new TypeError('invalid EDIT');
    return { draft: action.text, messages: copied };
  }
  if (action.type === 'SEND') {
    if (!sameKeys(action, ['type', 'id', 'sender']) || typeof action.id !== 'string' || action.id.length === 0 ||
        typeof action.sender !== 'string' || action.sender.length === 0) throw new TypeError('invalid SEND');
    const text = state.draft.trim();
    if (text.length === 0) return { draft: state.draft, messages: copied };
    return { draft: '', messages: copied.concat({ id: action.id, sender: action.sender, text }).slice(-50) };
  }
  if (action.type === 'RECEIVE') {
    if (!sameKeys(action, ['type', 'id', 'sender', 'text']) || typeof action.id !== 'string' || action.id.length === 0 ||
        typeof action.sender !== 'string' || action.sender.length === 0 || typeof action.text !== 'string') {
      throw new TypeError('invalid RECEIVE');
    }
    return { draft: state.draft, messages: copied.concat({ id: action.id, sender: action.sender, text: action.text.trim() }).slice(-50) };
  }
  throw new TypeError('unknown action');
}

module.exports = { createChatState, applyChatAction };

