'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['applyChatAction', 'createChatState']);
const { createChatState, applyChatAction } = api;
const typeError = fn => assert.throws(fn, TypeError);

const initial = createChatState();
assert.deepStrictEqual(initial, { draft: '', messages: [] });
assert.notStrictEqual(createChatState(), initial);
const edited = applyChatAction(initial, { type: 'EDIT', text: '  hello  ' });
assert.deepStrictEqual(edited, { draft: '  hello  ', messages: [] });
assert.notStrictEqual(edited, initial);
assert.notStrictEqual(edited.messages, initial.messages);
const sent = applyChatAction(edited, { type: 'SEND', id: 'm1', sender: 'me' });
assert.deepStrictEqual(sent, { draft: '', messages: [{ id: 'm1', sender: 'me', text: 'hello' }] });
const received = applyChatAction(sent, { type: 'RECEIVE', id: 'm2', sender: 'you', text: '  exact  ' });
assert.deepStrictEqual(received.messages[1], { id: 'm2', sender: 'you', text: '  exact  ' });
assert.notStrictEqual(received.messages, sent.messages);
assert.notStrictEqual(received.messages[0], sent.messages[0]);
received.messages[0].text = 'changed';
assert.strictEqual(sent.messages[0].text, 'hello');

const whitespace = { draft: ' \n ', messages: [{ id: 'x', sender: 's', text: 't' }] };
const noSend = applyChatAction(whitespace, { type: 'SEND', id: 'new', sender: 's' });
assert.deepStrictEqual(noSend, whitespace);
assert.notStrictEqual(noSend, whitespace);
assert.notStrictEqual(noSend.messages, whitespace.messages);
assert.notStrictEqual(noSend.messages[0], whitespace.messages[0]);

let state = createChatState();
for (let i = 1; i <= 51; i++) state = applyChatAction(state, { type: 'RECEIVE', id: `m${i}`, sender: 's', text: `${i}` });
assert.strictEqual(state.messages.length, 50);
assert.strictEqual(state.messages[0].id, 'm2');
assert.strictEqual(state.messages[49].id, 'm51');

typeError(() => applyChatAction(null, { type: 'EDIT', text: '' }));
typeError(() => applyChatAction({ draft: '', messages: [], extra: 1 }, { type: 'EDIT', text: '' }));
typeError(() => applyChatAction({ draft: 1, messages: [] }, { type: 'EDIT', text: '' }));
typeError(() => applyChatAction({ draft: '', messages: [{ id: '', sender: 's', text: 't' }] }, { type: 'EDIT', text: '' }));
typeError(() => applyChatAction(initial, { type: 'EDIT', text: 1 }));
typeError(() => applyChatAction(initial, { type: 'EDIT', text: '', extra: 1 }));
typeError(() => applyChatAction(initial, { type: 'SEND', id: '', sender: 's' }));
typeError(() => applyChatAction(initial, { type: 'SEND', id: 'x', sender: 's', text: 'x' }));
typeError(() => applyChatAction(initial, { type: 'RECEIVE', id: 'x', sender: 's', text: 1 }));
typeError(() => applyChatAction(initial, { type: 'OTHER' }));

